@js:
function formateTime(nS){
  var date = new Date(nS);
  Y = date.getFullYear() + '-';
  M = (date.getMonth()+1 < 10 ? '0'+(date.getMonth()+1) : date.getMonth()+1) + '-';
  D = date.getDate() + ' ';
  h = date.getHours() + ':';
  m = date.getMinutes() + ':';
  s = date.getSeconds(); 
  return Y+M+D+h+m+s
}
var max_page = parseInt(org.jsoup.Jsoup.parse(src).select("#index-select option:last-child").attr('value'));
var bkey = baseUrl.substr(baseUrl.lastIndexOf("bkey")+5,32)
var i = 1
var chapters = [];
for (let i=1;i<=max_page;i++){
  var res = java.post('https://yd.sogou.com/h5/cpt/ajax/detail?gf=e-d-pdetail-i&uID=-&sgid=0','p='+i+'&bkey='+bkey+'&asc=asc&pageSize=100',{}).body();
    items = JSON.parse(res).list.items.map((item)=>{
        item.url = 'https://yd.sogou.com/h5/cpt/chapter?bkey='+item.bkey+'&ckey='+item.ckey+'&gf=e-d-pdetail-i&uID=-&sgid=0';
        item.info = '字数：'+item.size+'  更新时间：'+formateTime(item.updateTime)
        item.isVip = !item.isFree;
        return item;
    })
    chapters = chapters.concat(items)
}
