html=""
if (!baseUrl.includes("_")) {
    doc = org.jsoup.Jsoup.parse(result).select("#content");
    doc.select(".posterror").remove();
    html += doc
} else {
    html += java.base64Decode(result.match(/var mytxt = '(.+)'/)[1])
}
html+"下页标识"

